package com.arlight.chatclient;
import net.minecraft.client.Minecraft;import java.nio.charset.StandardCharsets;import java.util.*;
public final class WardrobeState {public record Entry(String id,String name,String slot,String description,String rarity){} private static List<Entry> entries=List.of();private static Map<String,String> equipped=Map.of();private static final Base64.Decoder B=Base64.getUrlDecoder();private WardrobeState(){} public static void accept(String raw){String[] p=raw.split("\\|",-1);if(p.length==0)return;if(p[0].equals("OPEN")&&p.length>=3){List<Entry> out=new ArrayList<>();if(!p[1].isEmpty())for(String row:p[1].split(";")){String[] x=row.split(",",5);if(x.length==5)out.add(new Entry(dec(x[0]),dec(x[1]),x[2],dec(x[3]),dec(x[4])));}Map<String,String> eq=new HashMap<>();if(!p[2].isEmpty())for(String row:p[2].split(",")){String[] x=row.split("=",2);if(x.length==2)eq.put(x[0],dec(x[1]));}entries=List.copyOf(out);equipped=Map.copyOf(eq);Minecraft.getInstance().setScreen(new VisualWardrobeScreen());}} static String enc(String s){return Base64.getUrlEncoder().withoutPadding().encodeToString(s.getBytes(StandardCharsets.UTF_8));}public static String decPublic(String s){return dec(s);}
private static String dec(String s){try{return s.isEmpty()?"":new String(B.decode(s),StandardCharsets.UTF_8);}catch(Exception e){return "";}}public static List<Entry> entries(){return entries;}public static Map<String,String> equipped(){return equipped;}}
